param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session "hq";$agency=Session "agency";$client=Session "client";$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/abm";$workspace=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh;$used=@($workspace.targets|ForEach-Object {$_.account_reference});$source=$workspace.sources|Where-Object {$used -notcontains $_.account_reference -and $_.consented_member_count -ge $_.required_role_count}|Select-Object -First 1;if(-not $source){throw "Missing unused consent-covered account with published buying committee"}
$program=Post "$root/programs" @{program_code="STRATEGIC-ABM-$stamp";program_name="Governed strategic factory ABM $stamp";business_objective="Coordinate marketing, ads and sales across every verified buying role";allowed_consumers=@("crm","marketing","ads","sales")} $hh;$target=Post "$root/programs/$($program.id)/targets" @{audience_segment_id=$source.audience_segment_id;buying_committee_id=$source.buying_committee_id;priority_tier="tier-1";fit_score=92} $hh;$target=Post "$root/targets/$($target.id)/verify" @{expected_revision=$target.revision;reference="ABM-TARGET-VERIFY-$stamp"} $ah;$plays=@();$order=0;foreach($member in $source.members){$order++;$play=Post "$root/targets/$($target.id)/plays" @{committee_member_id=$member.id;owner_team=if($order -eq $source.members.Count){"marketing"}else{"sales"};channel=$member.channel;action_code="ROLE-$($member.role_code)";message_intent="Address $($member.role_name) decision criteria with verified evidence";success_signal="Verified buying-role response";sequence_order=$order} $hh;$plays+=Post "$root/plays/$($play.id)/approve" @{expected_revision=$play.revision;reference="ABM-PLAY-APPROVE-$order-$stamp"} $ah};if($plays.Count -ne $source.required_role_count){throw "ABM role coverage is incomplete"}
$published=Post "$root/programs/$($program.id)/publish" @{expected_revision=$program.revision;consumers=@("crm","marketing","ads","sales");delivery_reference_prefix="ABM-$stamp"} $ah;$acks=@();foreach($activation in $published.activations){$acks+=Post "$root/activations/$($activation.id)/acknowledge" @{expected_revision=$activation.revision;reference="ABM-ACTIVATION-ACK-$($activation.consumer)-$stamp"} $ch};$workspace=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh
[pscustomobject]@{project_id=$ProjectId;program_number=$published.program.program_number;version_reference=$published.version.version_reference;manifest_hash=$published.version.manifest_hash;target_count=$published.version.target_count;role_play_count=$published.version.role_play_count;role_coverage_percent=$published.version.role_coverage_percent;consumer_count=$acks.Count;acknowledged_activations=($acks|Where-Object {$_.status -eq "acknowledged"}).Count;hq=$hq.user.id;agency=$agency.user.id;client=$client.user.id;contract=$workspace.contract;metrics=$workspace.metrics}|ConvertTo-Json -Depth 8
